head.script:
///////// 1. 변수 및 선언 영역 /////////
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        /**********************************************
         * 함수명   : gform > onload
         * 설명      : 화면 Onload
         ***********************************************/
        $c.bns.BnsPanelToGroupBox(panel_Top);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        await scwin.getDate();
        edt_SDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
        edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25400.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        /**********************************************
         * 함수명   : btn_Search > onclick
         * 설명      : 조회버튼 클릭
         ***********************************************/
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25400.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        /**********************************************
         * 함수명   : btn_SDate > onclick
         * 설명      : 신청일기간 시작일자 달력클릭
         ***********************************************/
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25400.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        /**********************************************
         * 함수명   : btn_Excel > onclick
         * 설명      : 엑셀버튼 클릭
         ***********************************************/
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25400.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List3_OnLoadError
 * @description dts_List3 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List3_OnLoadError = async function() {
    try {
        /**********************************************
         * 함수명   : dts_List3 > OnLoadError
         * 설명      : dts_List3 조회 에러
         ***********************************************/
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25400.dts_List3_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List3_OnLoadCompleted
 * @description dts_List3 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    try {
        /**********************************************
         * 함수명   : dts_List3 > OnLoadError
         * 설명      : dts_List3 조회 성공
         ***********************************************/
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page3);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25400.dts_List3_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDate
 * @description 일자 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_getDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_getDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let vsTabSel = tab_Main.getSelectedTabIndex();
    let vsInOut = "";
    let vsSql = "";
    let voDtsList = null;
    let voGridList = null;
    vsInOut = "BNS_EARNG_RT_RCV_LIST3";
    vsSql = "lds.stf.bnsearng_rt_rcv.select.list3";
    voDtsList = dts_List3;
    voGridList = grd_List3;
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=" + vsInOut;
    url += "&queryId=" + vsSql;
    url += "&SCREN_ID=" + "ULDBNS25400.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_WORK_DT=" + edt_SDate.getValue();
    const sbmOptions = {
        id : "sbm_voDtsList",
        action : "/listingCommon.do",
        ref : "",
        target : "voDtsList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    let vsTabSel = tab_Main.getSelectedTabIndex();
    let voDtsList = null;
    let voGridList = null;
    let excelSheet = '';
    excelSheet = '스트립수익률';
    voDtsList = dts_List3;
    voGridList = grd_List3;
    if (voDtsList.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDBNS25400.xml", SCREN_PROCS_TP_CD_07);
        const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_수익률수신.xls";
        voGridList.GridToExcel(excelSheet, "", "8");
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
